 if not name.endswith('.pdf'):continue
 parts=name.split('/'); title=parts[-1][:-4].split('_ ',1)[-1].replace('_',' / ')
 unit=parts[1].split('_ ',1)[-1]; group=parts[1].split('_',1)[0].replace('Unit ','')
